from pysat.solvers import Solver
from pysat.card import CardEnc, EncType
import time

def solve_graceful_sat():
    V = 30
    E = 57

    edges = []
    for g in range(10):
        for i in range(3):
            for j in range(i+1, 3):
                edges.append((g * 3 + i, g * 3 + j))

    for g in range(9):
        for i in range(3):
            edges.append((g * 3 + i, (g + 1) * 3 + i))

    print(f"Vertices: {V}, Edges: {len(edges)}")

    # Variables:
    # x[i][v] : vertex i has label v (i in 0..V-1, v in 0..E)
    # e[j][d] : edge j has difference d (j in 0..E-1, d in 1..E)

    def x_var(i, v):
        return i * (E + 1) + v + 1

    def e_var(j, d):
        return V * (E + 1) + j * E + d

    solver = Solver(name='cadical')

    # 1. Each vertex has exactly one label
    for i in range(V):
        vars_i = [x_var(i, v) for v in range(E + 1)]
        solver.add_clause(vars_i)
        for c in CardEnc.atmost(vars_i, bound=1, vpool=None, encoding=EncType.seqcounter):
            solver.add_clause(c)

    # 2. Each label is assigned to at most one vertex
    for v in range(E + 1):
        vars_v = [x_var(i, v) for i in range(V)]
        for c in CardEnc.atmost(vars_v, bound=1, vpool=None, encoding=EncType.seqcounter):
            solver.add_clause(c)

    # 3. Edge differences
    for j, (u, w) in enumerate(edges):
        vars_j = [e_var(j, d) for d in range(1, E + 1)]
        solver.add_clause(vars_j)
        for c in CardEnc.atmost(vars_j, bound=1, vpool=None, encoding=EncType.seqcounter):
            solver.add_clause(c)

        for d in range(1, E + 1):
            # e[j][d] implies (x[u][v] and x[w][v+d]) or (x[u][v+d] and x[w][v]) for some v
            # Actually, it's easier to say: x[u][v] and x[w][v+d] implies e[j][d]
            for v in range(E + 1 - d):
                solver.add_clause([-x_var(u, v), -x_var(w, v + d), e_var(j, d)])
                solver.add_clause([-x_var(u, v + d), -x_var(w, v), e_var(j, d)])

            # e[j][d] implies one of the pairs
            # e[j][d] -> OR_{v} (x[u][v] AND x[w][v+d]) OR (x[u][v+d] AND x[w][v])
            # This can be encoded by adding clauses:
            # For each v, if x[u][v], then w must be v+d or v-d (if e[j][d] is true)
            # Wait, a simpler way:
            # If e[j][d] is true, then for each v, x[u][v] implies x[w][v+d] or x[w][v-d]
            for v in range(E + 1):
                possible_w = []
                if v + d <= E:
                    possible_w.append(x_var(w, v + d))
                if v - d >= 0:
                    possible_w.append(x_var(w, v - d))
                solver.add_clause([-e_var(j, d), -x_var(u, v)] + possible_w)

    # 4. Each difference is assigned to exactly one edge
    for d in range(1, E + 1):
        vars_d = [e_var(j, d) for j in range(E)]
        solver.add_clause(vars_d)
        for c in CardEnc.atmost(vars_d, bound=1, vpool=None, encoding=EncType.seqcounter):
            solver.add_clause(c)

    # Symmetry breaking
    solver.add_clause([x_var(0, 0)]) # We can't just set vertex 0 to 0, because 0 might be elsewhere.
    # Wait, graceful labeling doesn't guarantee vertex 0 is 0. But SOME vertex is 0, and SOME vertex is E.
    # The graph has symmetries.

    print("Solving...")
    start = time.time()
    if solver.solve():
        print(f"SAT in {time.time() - start:.2f}s")
        model = solver.get_model()
        labels = [-1] * V
        for i in range(V):
            for v in range(E + 1):
                if model[x_var(i, v) - 1] > 0:
                    labels[i] = v
        print(labels)
    else:
        print(f"UNSAT in {time.time() - start:.2f}s")

solve_graceful_sat()

