    # 1. Each vertex has exactly one label
    for i in range(V):
        vars_i = [x_var(i, v) for v in range(E + 1)]
        solver.add_clause(vars_i)
        for c in CardEnc.atmost(vars_i, bound=1, vpool=None, encoding=EncType.seqcounter):
