        for c in CardEnc.atmost(vars_v, bound=1, vpool=None, encoding=EncType.seqcounter):
            solver.add_clause(c)

    # 3. Edge differences
    for j, (u, w) in enumerate(edges):
        vars_j = [e_var(j, d) for d in range(1, E + 1)]
        solver.add_clause(vars_j)
        for c in CardEnc.atmost(vars_j, bound=1, vpool=None, encoding=EncType.seqcounter):
            solver.add_clause(c)

        for d in range(1, E + 1):
            for v in range(E + 1 - d):
                solver.add_clause([-x_var(u, v), -x_var(w, v + d), e_var(j, d)])
                solver.add_clause([-x_var(u, v + d), -x_var(w, v), e_var(j, d)])

            for v in range(E + 1):
                possible_w = []
                if v + d <= E:
                    possible_w.append(x_var(w, v + d))
                if v - d >= 0:
                    possible_w.append(x_var(w, v - d))
                solver.add_clause([-e_var(j, d), -x_var(u, v)] + possible_w)

    # 4. Each difference is assigned to exactly one edge
    for d in range(1, E + 1):
        vars_d = [e_var(j, d) for j in range(E)]
        solver.add_clause(vars_d)
        for c in CardEnc.atmost(vars_d, bound=1, vpool=None, encoding=EncType.seqcounter):
            solver.add_clause(c)

    # Symmetry breaking
    # The graph is a sequence of 10 K3s.
    # We can reverse the sequence: g -> 9-g
    # We can permute the vertices within the K3s simultaneously: i -> p(i)
    # Let's fix the first K3 to have sorted labels:
    # Actually, we can't just say x[0] < x[1] < x[2] because we don't know which is which.
    # But since the vertices within a clique are symmetric (and their connections to the next clique are parallel),
    # we can enforce that the labels of the first clique are sorted:
    # Wait, the connections are: vertex i of clique g is connected to vertex i of clique g+1.
    # So if we permute the vertices in clique 0, we must apply the SAME permutation to all other cliques.
    # Thus, we can assume the labels of clique 0 are sorted!
    # label(0) < label(1) < label(2)
    for v1 in range(E + 1):
        for v2 in range(v1 + 1):
            solver.add_clause([-x_var(0, v1), -x_var(1, v2)])
            solver.add_clause([-x_var(1, v1), -x_var(2, v2)])

    # Also, we can reverse the sequence of cliques.
    # To break this symmetry, we can require label(0) < label(27) (first vertex of first clique vs first vertex of last clique)
    # Wait, is label(0) necessarily the smallest in the first clique? Yes, we just enforced it.
    # Is label(27) the smallest in the last clique? Not necessarily.
    # But reversing the sequence of cliques maps clique 0 to clique 9, and clique 9 to clique 0.
    # It maps vertex (0, i) to (9, i).
    # So we can just enforce label(0) < label(27).
    for v1 in range(E + 1):
        for v2 in range(v1 + 1):
            solver.add_clause([-x_var(0, v1), -x_var(27, v2)])

    # Graceful labeling symmetry: L' = E - L
    # We can enforce that the smallest label is 0, and the largest is E.
    # Actually, in any graceful labeling, 0 and E must be present.
    # We can enforce that the label 0 is assigned to a vertex in the first half of the graph.
    # Or simply, label(0) + label(1) < E ? No.
    # Let's just let it run.

    print("Solving...")
    start = time.time()
    if solver.solve():
        print(f"SAT in {time.time() - start:.2f}s")
        model = solver.get_model()
        labels = [-1] * V
        for i in range(V):
