from pysat.solvers import Solver
from pysat.card import CardEnc
from pysat.formula import IDPool

def solve_n(n):
    V = 3 * n
    E = 3 * n + 3 * (n - 1)

    edges = []
    for g in range(n):
        for i in range(3):
            for j in range(i+1, 3):
                edges.append((g * 3 + i, g * 3 + j))

    for g in range(n - 1):
        for i in range(3):
            edges.append((g * 3 + i, (g + 1) * 3 + i))

    vpool = IDPool()
    def x_var(i, v): return vpool.id(f'x_{i}_{v}')
    def e_var(j, d): return vpool.id(f'e_{j}_{d}')

    solver = Solver(name='g3')

    for i in range(V):
        vars_i = [x_var(i, v) for v in range(E + 1)]
        solver.add_clause(vars_i)
        for c in CardEnc.atmost(vars_i, bound=1, vpool=vpool): solver.add_clause(c)

    for v in range(E + 1):
        vars_v = [x_var(i, v) for i in range(V)]
        for c in CardEnc.atmost(vars_v, bound=1, vpool=vpool): solver.add_clause(c)

    for j, (u, w) in enumerate(edges):
        vars_j = [e_var(j, d) for d in range(1, E + 1)]
        solver.add_clause(vars_j)
        for c in CardEnc.atmost(vars_j, bound=1, vpool=vpool): solver.add_clause(c)

        for d in range(1, E + 1):
            for v in range(E + 1 - d):
                solver.add_clause([-x_var(u, v), -x_var(w, v + d), e_var(j, d)])
                solver.add_clause([-x_var(u, v + d), -x_var(w, v), e_var(j, d)])
            for v in range(E + 1):
                possible_w = []
                if v + d <= E: possible_w.append(x_var(w, v + d))
                if v - d >= 0: possible_w.append(x_var(w, v - d))
                solver.add_clause([-e_var(j, d), -x_var(u, v)] + possible_w)

    for d in range(1, E + 1):
        vars_d = [e_var(j, d) for j in range(E)]
        solver.add_clause(vars_d)
        for c in CardEnc.atmost(vars_d, bound=1, vpool=vpool): solver.add_clause(c)

    # Symmetry breaking
    for v1 in range(E + 1):
        for v2 in range(v1 + 1):
            solver.add_clause([-x_var(0, v1), -x_var(1, v2)])
            solver.add_clause([-x_var(1, v1), -x_var(2, v2)])

    if solver.solve():
        model = solver.get_model()
        labels = [-1] * V
        for i in range(V):
            for v in range(E + 1):
                if model[x_var(i, v) - 1] > 0:
                    labels[i] = v
        return labels
    return None

